// Alienmon that roam inside the patch and can pop out of the grass when Rook walks through.
const TG = [], TGP = [];
const TGK = { // blade colours (root -> tip), seed-head glow, and who lives there
  meadow: { lo: "#1e5a2a", hi: "#b8f07a", seed: "#e8ff9a", mons: ["lo_sporix", "lo_chirpod", "lo_blinkit"] },
  fen: { lo: "#1a4a4a", hi: "#7ae0c8", seed: "#9af0ff", mons: ["lo_gloopa", "lo_mycora", "lo_gloopa"] },
  spore: { lo: "#4a2a5a", hi: "#ff9ad8", seed: "#ffd0f0", mons: ["lo_dreamcap", "lo_blinkit", "lo_sporix"] },
  ember: { lo: "#5a3a1a", hi: "#ffc860", seed: "#fff0a0", mons: ["lo_chirpod", "lo_pebblet", "lo_sporix"] },
  rocky: { lo: "#3a4a3a", hi: "#a8c890", seed: "#d8e8c0", mons: ["lo_pebblet", "lo_pebblet", "lo_mycora"] },
  glow: { lo: "#163a4a", hi: "#5af0ff", seed: "#c8ffff", mons: ["lo_blinkit", "lo_dreamcap", "lo_mycora"] } };
const tgUnwarp = (x, z) => (TER.ready && TER.low ? unwarp(x, z) : [x, z]);
