  const bg = new THREE.PlaneGeometry(0.13, 1, 1, 6); bg.translate(0, 0.5, 0); { const P = bg.attributes.position, ty = []; for (let i = 0; i < P.count; i++) { const y = P.getY(i); P.setX(i, P.getX(i) * (1 - y * y * 0.85)); P.setZ(i, y * y * 0.38); ty.push(y); } bg.setAttribute("tgy", new THREE.Float32BufferAttribute(ty, 1)); bg.computeVertexNormals(); }
