  mat.userData.tg = true; const ob = mat.onBeforeCompile; mat.onBeforeCompile = (sh, r) => { ob && ob(sh, r); sh.vertexShader = "attribute vec3 tgLo; attribute float tgy; varying vec3 vTgLo; varying float vTgY;\n" + sh.vertexShader.replace("#include <begin_vertex>", "#include <begin_vertex>\n vTgLo = tgLo; vTgY = tgy;"); sh.fragmentShader = "varying vec3 vTgLo; varying float vTgY;\n" + sh.fragmentShader.replace("#include <color_fragment>", "#include <color_fragment>\n diffuseColor.rgb = mix(vTgLo, diffuseColor.rgb, smoothstep(0.0, 1.0, vTgY));"); }; const ck = mat.customProgramCacheKey ? mat.customProgramCacheKey.bind(mat) : () => ""; mat.customProgramCacheKey = () => ck() + "tg";
  const IM = new THREE.InstancedMesh(bg, mat, TG.length), lo = new Float32Array(TG.length * 3), m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), e = new THREE.Euler(), v = new THREE.Vector3(), sc = new THREE.Vector3(), cc = new THREE.Color();
  TG.forEach(([x, z, h, r, kind], i) => { const K = TGK[kind] || TGK.meadow; e.set((R() - 0.5) * 0.35, r, (R() - 0.5) * 0.35); q.setFromEuler(e); v.set(x, Math.max(GHT(x, z), 0) - 0.03, z); sc.set(1 + R() * 0.4, h, 1); m4.compose(v, q, sc); IM.setMatrixAt(i, m4); cc.set(K.hi).offsetHSL((R() - 0.5) * 0.04, 0, (R() - 0.5) * 0.1); IM.setColorAt(i, cc); cc.set(K.lo); lo[i * 3] = cc.r; lo[i * 3 + 1] = cc.g; lo[i * 3 + 2] = cc.b; });
  bg.setAttribute("tgLo", new THREE.InstancedBufferAttribute(lo, 3)); IM.castShadow = false; IM.receiveShadow = true; IM.name = "grass"; root.add(IM);
  // glowing seed heads on one blade in nine
